'use client';

import { useEffect, useMemo, useState } from 'react';
import GridMotion from './GridMotion';
// Generated by scripts/gen-culturals.mjs (runs before dev/build): every photo in public/assets/culturals.
import photos from '@/data/culturals.json';

const ROWS = 4;
const ALT = 'TKM MUN Cultural Night performance';

// Small seeded PRNG so server and client render the same order (no hydration mismatch).
const mulberry32 = (seed) => () => {
  seed |= 0;
  seed = (seed + 0x6d2b79f5) | 0;
  let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
};

const shuffle = (list, rand) => {
  const a = [...list];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
};

/** Fills ROWS x cols with photos; repeats in shuffled order but never beside (or above/below) itself. */
function buildTiles(list, cols, offset) {
  const count = ROWS * cols;
  if (!list.length) return [];
  const rand = mulberry32(26);
  let pool;
  if (list.length >= count) {
    const o = offset % list.length;
    pool = [...list.slice(o), ...list.slice(0, o)].slice(0, count);
  } else {
    pool = [];
    while (pool.length < count + list.length) pool.push(...shuffle(list, rand));
  }
  const placed = [];
  for (let i = 0; i < count; i++) {
    const left = i % cols ? placed[i - 1] : null;
    const above = i >= cols ? placed[i - cols] : null;
    let k = pool.findIndex((p) => p !== left && p !== above);
    if (k < 0) k = 0;
    placed.push(pool.splice(k, 1)[0]);
  }
  return placed;
}

// 7 columns on desktop, 3 on tablet, 2 on phone.
function useCols() {
  const [cols, setCols] = useState(7);
  useEffect(() => {
    const update = () => setCols(window.innerWidth < 640 ? 2 : window.innerWidth < 1024 ? 3 : 7);
    update();
    window.addEventListener('resize', update);
    return () => window.removeEventListener('resize', update);
  }, []);
  return cols;
}

function Tile({ src }) {
  return (
    <div className="group relative h-full w-full overflow-hidden rounded-[5px] border border-gold/35 bg-maroon-dark">
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        src={src}
        alt={ALT}
        loading="lazy"
        decoding="async"
        draggable={false}
        className="absolute inset-0 h-full w-full object-cover sepia-[.1] transition-[filter] duration-500 group-hover:sepia-0"
      />
      <div className="pointer-events-none absolute inset-0 bg-maroon-dark/[0.07] transition-opacity duration-500 group-hover:opacity-0" />
    </div>
  );
}

export default function CulturalGallery() {
  const cols = useCols();
  // Rotate which photos show when there are more than fit (set after mount so SSR stays stable).
  const [offset, setOffset] = useState(0);
  useEffect(() => setOffset(Math.floor(Math.random() * photos.length)), []);

  const items = useMemo(
    () => buildTiles(photos, cols, offset).map((src, i) => <Tile key={`${src}-${i}`} src={src} />),
    [cols, offset]
  );

  return (
    <section id="culturals" className="relative z-10 mx-auto max-w-7xl px-5 py-16 md:px-12 md:py-24">
      <div className="relative h-[78svh] min-h-[460px] overflow-hidden rounded-lg border border-gold/25 bg-oxblood md:h-[90vh]">
        <GridMotion items={items} cols={cols} gradientColor="rgba(88, 33, 25, 1)">
          {/* Blend into the sections above and below. */}
          <div className="pointer-events-none absolute inset-x-0 top-0 z-[3] h-[14%] bg-gradient-to-b from-oxblood to-transparent" />
          <div className="pointer-events-none absolute inset-x-0 bottom-0 z-[3] h-[14%] bg-gradient-to-t from-oxblood to-transparent" />

          <div className="pointer-events-none absolute inset-0 z-[4] flex items-center justify-center px-6">
            <div
              className="text-center"
              style={{
                background: 'radial-gradient(ellipse at center, rgba(88,33,25,0.7) 0%, rgba(88,33,25,0.45) 40%, rgba(88,33,25,0) 70%)',
                padding: 'clamp(2.5rem, 6vw, 4.5rem) clamp(1rem, 6vw, 4rem)',
                maxWidth: '100%',
              }}
            >
              <span className="font-display text-[10px] font-bold uppercase tracking-[0.25em] text-gold-light">After the Resolutions</span>
              <h2 className="mt-1 font-cormorant text-3xl font-semibold uppercase tracking-[0.18em] text-gold-light sm:text-4xl lg:text-5xl [text-shadow:0_2px_14px_rgba(40,16,12,0.9)]">
                Last MUN Cultural Night
              </h2>
              <div className="mx-auto mt-4 flex items-center justify-center gap-3" aria-hidden="true">
                <span className="h-px w-12 bg-gold/70 md:w-20" />
                <span className="h-1.5 w-1.5 rotate-45 bg-gold" />
                <span className="h-px w-12 bg-gold/70 md:w-20" />
              </div>
              <p className="mx-auto mt-4 max-w-md text-base text-cream md:text-lg [text-shadow:0_1px_10px_rgba(40,16,12,0.95)]">
                An evening of music, dance and drama once the committees adjourned.
              </p>
            </div>
          </div>
        </GridMotion>
      </div>
    </section>
  );
}
